import React from "react";

const PP = ({ page }) => {
  // sometimes there is article no only when published online.
  return page ? <span>, pp.{page}</span> : null;
};

const Vol = ({ volume }) => {
  // in case it does not have vol
  return volume ? <span>, vol.{volume}</span> : null;
};

const No = ({ number }) => {
  // some journal does not have number
  return number ? <span>, no.{number}</span> : null;
};


const Journal = ({ cite }) => {
  return (
    <span>
      {cite.container_title}
      <Vol volume={cite.volume} />
      <No number={cite.issue} />
      <PP page={cite.page} />
    </span>
  );
};

export default Journal;
